/// Inspects the Snapshot artifact recorded for `request_id`: digest
/// integrity, decryptability, and `pg_restore --list` archive validity.
/// Refuses (`409`) when the request has no `succeeded` receipt to inspect --
/// a failed or refused Snapshot never produced an artifact.
pub(super) async fn inspect_snapshot(
    State(state): State<AdministrationApiState>,
    Path(request_id): Path<String>,
) -> Result<Json<RecoveryInspectionResponse>, StatusCode> {
    let Some(snapshot_config) = state.snapshot.clone() else {
        return Err(StatusCode::SERVICE_UNAVAILABLE);
    };

    let (artifact_path, manifest_digest) = {
        let mut administration = state.administration.lock().await;
        // The request itself names its `requested_by` principal; only the
        // tenant that made it may inspect its artifact, mirroring every
        // other Snapshot/purge ownership check in this module.
        let request = administration
            .snapshot_request(&request_id)
            .await
            .map_err(administration_error_status)?
            .ok_or(StatusCode::NOT_FOUND)?;
        if request.requested_by != state.tenant_id.as_ref() {
            return Err(StatusCode::NOT_FOUND);
        }
        let receipt = administration
            .snapshot_receipt_for_request(&request_id)
            .await
            .map_err(administration_error_status)?
            .ok_or(StatusCode::CONFLICT)?;
        match (receipt.artifact_path, receipt.manifest_digest) {
            (Some(path), Some(digest)) => (path, digest),
            _ => return Err(StatusCode::CONFLICT),
        }
    };

    let now = SystemTime::now();
    let report = snapshot_provider::inspect_snapshot_artifact(
        &snapshot_config,
        &artifact_path,
        &manifest_digest,
    )
    .await
    .map_err(|error| {
        tracing::error!(%error, "Bridge Recovery inspection failed to run");
        StatusCode::INTERNAL_SERVER_ERROR
    })?;

    let mut administration = state.administration.lock().await;
    let inspection = administration
        .record_recovery_inspection(
            &NewRecoveryInspection {
                request_id,
                requested_by: state.tenant_id.to_string(),
                integrity_verified: report.integrity_verified,
                decryption_verified: report.decryption_verified,
                archive_valid: report.archive_valid,
                archive_entry_count: report.archive_entry_count,
                reason: report.reason,
                occurred_at: now,
            },
            now,
        )
        .await
        .map_err(administration_error_status)?;
    Ok(Json(inspection.into()))
}

pub(super) async fn latest_snapshot_inspection(
    State(state): State<AdministrationApiState>,
    Path(request_id): Path<String>,
) -> Result<Json<RecoveryInspectionResponse>, StatusCode> {
    let mut administration = state.administration.lock().await;
    let request = administration
        .snapshot_request(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    if request.requested_by != state.tenant_id.as_ref() {
        return Err(StatusCode::NOT_FOUND);
    }
    let inspection = administration
        .latest_recovery_inspection(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    Ok(Json(inspection.into()))
}

fn unix_seconds(timestamp: SystemTime) -> Option<u64> {
    timestamp
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_secs())
}
